# KairoX86#262: the JEGA's Japanese text (jega_render_text) on the GPU as text cells through a 33-colour line palette,
# a double-byte character two cells (jega_render_text_gpu, worked out as the CPU works out its pixels); the CPU's
# drawing stays as it was, touching its row first.
KAIROX86_GPU_JEGA = [
    ('86box/src/video/vid_jega.c',
     '#include <86box/vid_svga.h>\n#include <86box/vid_vga.h>\n',
     '#include <86box/vid_svga.h>\n#include <86box/kairo_gpu.h> /* KairoX86#262 */\n#include <86box/vid_vga.h>\n'),
    ('86box/src/video/vid_jega.c',
     '\n/* Display Adapter Mode 3 Drawing */\n',
     "\n/* KairoX86#262: the line's palette: the 16 EGA colours as the JEGA attributes take them (0-15), through the DAC mask\n   as the EGA attributes take them (16-31), and black (32) */\n#define JEGA_K_MASKED 16u\n#define JEGA_K_BLACK  32u\n#define JEGA_K_CELLS  512\n\n/* KairoX86#262: jega_render_text's line as text cells (86box/kairo_gpu.h KAIRO_SCAN_TEXT: 8 dots each, a double-byte\n   character two of them) to the GPU's scanout queue at p, worked out as the CPU works out its pixels; returns whether\n   the GPU draws it (not when another renderer may draw on the line, or it has more cells than JEGA_K_CELLS) */\nstatic bool\njega_render_text_gpu(jega_t *jega, uint32_t *p, uint8_t *vram, int sc, int hdisp, int scrollcache, uint32_t *memaddr,\n                     uint8_t mask, bool blinked, bool crtcreset, bool attrblink)\n{\n    if (!kairo_gpu_on || (jega->is_vga && !jega->vga.svga.render_async))\n        return false;\n    static uint32_t cells[JEGA_K_CELLS];\n    uint32_t        colours[33];\n    uint32_t        n          = 0;\n    uint32_t        ma         = *memaddr;\n    bool            chr_wide   = false;\n    int             sc_wide    = sc - jega->start_scan_count;\n    const bool      cursoron   = (blinked || jega->cursorblink_disable) && (sc >= jega->regs[RCCSL]) && (sc <= jega->regs[RCCEL]);\n    uint32_t        attr_basic = 0;\n    uint32_t        chr_first  = 0;\n    uint32_t        fg         = JEGA_K_BLACK;\n    uint32_t        bg         = JEGA_K_BLACK;\n\n    for (int i = 0; i < 16; i++) {\n        colours[i]                 = jega->pallook[jega->egapal[i]];\n        colours[JEGA_K_MASKED + i] = jega->pallook[jega->egapal[i] & mask];\n    }\n    colours[JEGA_K_BLACK] = 0;\n    for (int x = 0; x < (hdisp + scrollcache); x += 8) {\n        if (n + 2 > JEGA_K_CELLS)\n            return false;\n        uint32_t addr = 0;\n        if (jega->is_vga) {\n            if (!jega->vga.svga.force_old_addr)\n                addr = jega->vga.svga.remap_func(&jega->vga.svga, ma) & jega->vga.svga.vram_display_mask;\n        } else\n            addr = jega->ega.remap_func(&jega->ega, ma) & jega->ega.vrammask;\n        const int drawcursor = ((ma == jega->cursoraddr) && cursoron);\n        uint32_t  chr        = crtcreset ? 0 : vram[addr];\n        uint32_t  attr       = crtcreset ? 0 : vram[addr + 1];\n        const uint32_t pair  = (fg << 8) | (bg << 16);\n        if (chr_wide) {\n            uint8_t attr_ext = 0;\n            if (jega->regs[RMOD2] & 0x40) {\n                attr_ext = attr;\n                if ((attr_ext & 0x30) == 0x30)\n                    sc_wide = sc - jega->start_scan_lower;\n                else if ((attr_ext & 0x30) == 0x20)\n                    sc_wide = sc - jega->start_scan_upper;\n                else\n                    sc_wide = sc - jega->start_scan_count;\n            }\n            uint32_t dots = 0; /* the 16 dots, the leftmost bit 15 */\n            if (is_SJIS_2(chr) && sc_wide >= 0 && sc_wide < 16 && sc <= jega->regs[RPESL]) {\n                chr |= chr_first << 8;\n                if (attr_ext & 0x20)\n                    sc_wide = (attr_ext & 0x10) ? ((sc_wide >> 1) + 8) : (sc_wide >> 1);\n                if (attr_ext & 0x40) {\n                    uint32_t dat = dbcs_read(chr, sc_wide, jega);\n                    if (!(attr_ext & 0x08))\n                        dat = dbcs_read(chr, sc_wide + 16, jega);\n                    for (int xx = 0; xx < 8; xx++)\n                        if (dat & (0x80 >> xx))\n                            dots |= 0xc000u >> (xx * 2);\n                } else {\n                    uint32_t dat = (dbcs_read(chr, sc_wide, jega) << 8) | dbcs_read(chr, sc_wide + 16, jega);\n                    if (attr_ext & 0x80)\n                        dat |= dat >> 1;\n                    dots = dat & 0xffff;\n                }\n            }\n            if (attr_basic & 0x20)\n                dots |= 0x8000;\n            if ((sc == jega->regs[RPULP]) && (attr_basic & 0x10))\n                dots = 0xffff;\n            cells[n++] = (dots >> 8) | pair;\n            cells[n++] = (dots & 0xff) | pair;\n            chr_wide   = false;\n        } else {\n            if (jega->regs[RMOD2] & 0x80) {\n                if (drawcursor || attr & 0x40) {\n                    bg = attr & 0x0f;\n                    fg = JEGA_K_BLACK;\n                } else {\n                    fg = attr & 0x0f;\n                    bg = JEGA_K_BLACK;\n                    if ((attr & 0x80) && blinked)\n                        fg = bg;\n                }\n                attr_basic = attr;\n            } else {\n                if (drawcursor) {\n                    bg = JEGA_K_MASKED + (attr & 0x0f);\n                    fg = JEGA_K_MASKED + (attr >> 4);\n                } else {\n                    fg = JEGA_K_MASKED + (attr & 0x0f);\n                    bg = JEGA_K_MASKED + (attr >> 4);\n                    if ((attr & 0x80) && attrblink) {\n                        bg = JEGA_K_MASKED + ((attr >> 4) & 7);\n                        if (blinked)\n                            fg = bg;\n                    }\n                }\n                attr_basic = 0;\n            }\n            if (is_SJIS_1(chr)) {\n                chr_first = chr;\n                chr_wide  = true;\n            } else {\n                uint32_t dots = jega->jfont_sbcs_19[chr * 19 + sc];\n                if (attr_basic & 0x20)\n                    dots |= 0x80;\n                if ((sc == jega->regs[RPULP]) && (attr_basic & 0x10))\n                    dots = 0xff;\n                cells[n++] = (dots & 0xff) | (fg << 8) | (bg << 16);\n            }\n        }\n        ma += 4;\n    }\n    if (n == 0)\n        return false;\n    bitmap_t *bitmap = buffer32;\n    uint32_t *line   = kairo_gpu_scan(bitmap, bitmap->kairo_gpu, (uint32_t) (p - bitmap->dat), KAIRO_SCAN_TEXT, n * 8, n, colours, 33,\n                                      8, 0, 0);\n    memcpy(line, cells, n * sizeof(uint32_t));\n    kairo_gpu_scan_commit();\n    *memaddr = ma & 0x3ffff;\n    return true;\n}\n\n/* Display Adapter Mode 3 Drawing */\n"),
    ('86box/src/video/vid_jega.c',
     '        int        bg            = 0;\n\n',
     '        int        bg            = 0;\n\n        /* KairoX86#262: the GPU draws the line, else the CPU (after what the GPU still has to draw there) */\n        if (jega_render_text_gpu(jega, p, vram, *sc, *hdisp, *scrollcache, memaddr, mask, blinked, crtcreset, attrblink))\n            return;\n        if (kairo_gpu_on)\n            kairo_gpu_scan_touch(buffer32, (uint32_t) (p - buffer32->dat), (uint32_t) (buffer32->w - *x_add));\n\n'),
]

# KairoX86#255: the Genius VHR's text on the GPU when it is the line's only layer (no graphics under the MDA text, no
# MDA text over the CGA's), when its transparent drawing comes out as plain text: as text cells (9 dots, or 8 doubled),
# coloured as the CPU colours them. Text over graphics stays the CPU's.
KAIROX86_GPU_GENIUS_TEXT = [
    ('86box/src/video/vid_genius.c',
     '\n    for (int x = 0; x < w; x++) {\n',
     "\n    /* KairoX86#255: text that is the line's only layer (no graphics under the MDA text, no MDA text over the CGA's)\n       draws as plain text, its background pixels the line's own: the GPU draws it as text cells, coloured as the CPU\n       colours them. Not while the card is disabled, when its dots and its ninth column take different colours. */\n    if (kairo_gpu_on && genius->enabled && (ctrl & 8) && (w > 0) && (mda ? !(genius->cga_ctrl & 8) : !(genius->mda_ctrl & 8))) {\n        bitmap_t *bm    = buffer32;\n        uint32_t *cells = kairo_gpu_scan(bm, bm->kairo_gpu, (uint32_t) (bm->line[dl] - bm->dat), KAIRO_SCAN_TEXT,\n                                         (uint32_t) (w * cw * (cols80 ? 1 : 2)), (uint32_t) w, pal_lookup, 256, (uint32_t) cw, 0,\n                                         cols80 ? 0 : KAIRO_SCAN_WIDE);\n        for (int x = 0; x < w; x++) {\n            chr        = framebuf[(addr + 2 * x) & 0x3FFF];\n            attr       = framebuf[(addr + 2 * x + 1) & 0x3FFF];\n            drawcursor = ((memaddr == cursoraddr) && cursorline && genius->enabled && (ctrl & 8));\n            switch (crtc[10] & 0x60) {\n                case 0x00:\n                    drawcursor = drawcursor && (genius->blink & 16);\n                    break;\n                case 0x60:\n                    drawcursor = drawcursor && (genius->blink & 32);\n                    break;\n                default:\n                    break;\n            }\n            blink = ((genius->blink & 16) && (ctrl & 0x20) && (attr & 0x80) && !drawcursor);\n            if (ctrl & 0x20)\n                attr &= 0x7F;\n            const uint32_t inv = (genius->genius_control & 0x20) ? 15 : 0;\n            if (mda && (scanline == charh) && ((attr & 7) == 1)) {\n                /* The underline: every dot one colour */\n                const uint32_t u = (uint32_t) mdaattr[attr][blink][1] ^ inv;\n                cells[x]         = 0xff | (u << 8) | (u << 16) | (1u << 24);\n                continue;\n            }\n            const uint32_t dat   = mda ? fontdat8x12[chr][scanline] : fontdat[chr][scanline];\n            uint32_t       fg    = (uint32_t) mdaattr[attr][blink][1] ^ inv;\n            uint32_t       bg    = (uint32_t) mdaattr[attr][blink][0] ^ inv;\n            const bool     ninth = (cw == 9) && ((chr & ~0x1f) == 0xc0) && (dat & 1);\n            if (drawcursor) {\n                fg ^= (uint32_t) mdaattr[attr][0][1];\n                bg ^= (uint32_t) mdaattr[attr][0][1];\n            }\n            cells[x] = dat | ((fg & 0xff) << 8) | ((bg & 0xff) << 16) | (ninth ? (1u << 24) : 0);\n            ++memaddr;\n        }\n        kairo_gpu_scan_commit();\n        return;\n    }\n\n    for (int x = 0; x < w; x++) {\n"),
]

# KairoX86#241: CGA composite output decoded on the GPU (KAIRO_SCAN_COMPOSITE, 86box/kairo_gpu.h; scanout.comp): the
