# KairoX86#312: the Compaq Portable III's plasma on the GPU (compaq_plasma_render_gpu): each text cell's dots and
# two colours as the CPU's last drawing of it leaves them (the high-intensity modes' dimming and inversion), graphics
# as 1 bit a pixel.
KAIROX86_GPU_PLASMA = [
    ('86box/src/video/vid_cga_compaq_plasma.c',
     '#include <86box/vid_cga.h>\n#include <86box/vid_cga_comp.h>\n',
     '#include <86box/vid_cga.h>\n#include <86box/kairo_gpu.h> /* KairoX86#312 */\n#include <86box/vid_cga_comp.h>\n'),
    ('86box/src/video/vid_cga_compaq_plasma.c',
     '}\n\nstatic void\ncompaq_plasma_poll(void *priv)\n',
     "}\n\n/* KairoX86#312: colour c's place in a line's palette (n of them so far, up to 16), -1 when it is full */\nstatic int\nplasma_k_colour(uint32_t *palette, uint32_t *n, uint32_t c)\n{\n    for (uint32_t i = 0; i < *n; i++)\n        if (palette[i] == c)\n            return (int) i;\n    if (*n == 16)\n        return -1;\n    palette[*n] = c;\n    return (int) (*n)++;\n}\n\n/* KairoX86#312: a colour at half its brightness, each channel halved (the high-intensity attribute's dimming) */\nstatic uint32_t\nplasma_half(uint32_t c)\n{\n    return ((c & 0xff) >> 1) | ((((c >> 8) & 0xff) >> 1) << 8) | ((((c >> 16) & 0xff) >> 1) << 16);\n}\n\n/* KairoX86#312: the plasma's line (compaq_plasma_poll's text or graphics, read as it reads it) to the GPU's scanout\n   queue in the colours it draws: each text cell's dots and two colours as the CPU's last drawing of it leaves them.\n   Returns whether the GPU draws it; when not (the light pen, which reads the picture back, or a text line of more\n   than 16 colours, which never comes), the row is touched first, for the CPU to draw it. */\nstatic bool\ncompaq_plasma_render_gpu(compaq_plasma_t *self, uint16_t memaddr, uint16_t cursoraddr)\n{\n    bitmap_t      *bitmap  = buffer32;\n    const uint32_t out     = (uint32_t) (bitmap->line[self->cga.displine] - bitmap->dat);\n    const bool     enabled = (self->cga.cgamode & 0x08) != 0;\n\n    if (!kairo_gpu_on)\n        return false;\n    if (cga_lightpen_enabled) {\n        kairo_gpu_scan_touch(bitmap, out, (uint32_t) bitmap->w);\n        return false;\n    }\n    if (self->cga.cgamode & 0x02) { /* graphics */\n        uint16_t addr;\n        uint32_t colours[2];\n        uint8_t *bytes;\n        if (self->cga.cgamode & CGA_MODE_FLAG_HIGHRES_GRAPHICS) {\n            if (self->port_23c6 & 0x01) /* 640 x 400 */\n                addr = ((self->cga.displine) & 1) * 0x2000 + ((self->cga.displine >> 1) & 1) * 0x4000 + (self->cga.displine >> 2) * 80 + ((memaddr & ~1) << 1);\n            else\n                addr = ((self->cga.displine >> 1) & 1) * 0x2000 + (self->cga.displine >> 2) * 80 + ((memaddr & ~1) << 1);\n            colours[0] = black;\n            colours[1] = enabled ? ((self->cga.cgacol & 0x0f) ? amber : black) : black;\n            bytes      = (uint8_t *) kairo_gpu_scan(bitmap, bitmap->kairo_gpu, out, KAIRO_SCAN_BITS, 640, 20, colours, 2, 1, 0, 0);\n            for (int x = 0; x < 80; x++)\n                bytes[x] = self->cga.vram[(addr + x) & 0x7fff];\n        } else { /* 320 wide: each pixel two dots of amber or black, dithered by the line */\n            addr       = ((self->cga.displine >> 1) & 1) * 0x2000 + (self->cga.displine >> 2) * 80 + ((memaddr & ~1) << 1);\n            colours[0] = black;\n            colours[1] = amber;\n            bytes      = (uint8_t *) kairo_gpu_scan(bitmap, bitmap->kairo_gpu, out, KAIRO_SCAN_BITS, 640, 20, colours, 2, 1, 0, 0);\n            for (int x = 0; x < 80; x++) {\n                uint8_t  dat  = self->cga.vram[(addr + x) & 0x7fff];\n                uint32_t dots = 0;\n                for (int c = 0; c < 4; c++) {\n                    const uint8_t pattern = enabled ? ((dat & 0xC0) >> 6) : 0;\n                    uint32_t      two     = 0;\n                    switch (pattern & 3) {\n                        case 1:\n                            two = (self->cga.displine & 1) ? 0 : 2;\n                            break;\n                        case 2:\n                            two = (self->cga.displine & 1) ? 1 : 2;\n                            break;\n                        case 3:\n                            two = 3;\n                            break;\n                        default:\n                            break;\n                    }\n                    dots = (dots << 2) | two;\n                    dat <<= 2;\n                }\n                bytes[x] = (uint8_t) dots;\n            }\n        }\n        kairo_gpu_scan_commit();\n        return true;\n    }\n\n    /* Text: 80 columns, or 40 each dot twice across; 16 lines a row */\n    const int      cols     = (self->cga.cgamode & 0x01) ? 80 : 40;\n    const uint8_t  scanline = self->cga.displine & 0x0f;\n    const uint16_t addr     = ((memaddr & ~1) + (self->cga.displine >> 4) * cols) << 1;\n    uint16_t       ma       = memaddr + (self->cga.displine >> 4) * cols;\n    const uint32_t X        = amber ^ black;\n    const uint32_t XH       = plasma_half(amber) ^ plasma_half(black);\n    const unsigned hi_mode  = self->port_23c6 >> 5;\n    int            cursorline;\n    uint32_t       palette[16];\n    uint32_t       n = 0;\n    uint32_t       cells[80];\n\n    if ((self->cga.crtc[CGA_CRTC_CURSOR_START] & 0x60) == 0x20)\n        cursorline = 0;\n    else {\n        const int visible   = ((self->cga.crtc[CGA_CRTC_CURSOR_START] & 0x0f) > 0x07) ? (self->cga.crtc[CGA_CRTC_CURSOR_START] & 0x0f) + 1\n                                                                                    : ((self->cga.crtc[CGA_CRTC_CURSOR_START] & 0x0f) << 1);\n        const int invisible = ((self->cga.crtc[CGA_CRTC_CURSOR_END] & 0x0f) > 0x07) ? (self->cga.crtc[CGA_CRTC_CURSOR_END] & 0x0f) + 2\n                                                                                  : ((self->cga.crtc[CGA_CRTC_CURSOR_END] & 0x0f) << 1);\n        cursorline = (visible <= scanline) && (invisible >= scanline);\n    }\n    for (int x = 0; x < cols; x++) {\n        uint8_t       chr        = enabled ? self->cga.vram[(addr + (x << 1)) & 0x7fff] : 0x00;\n        uint8_t       attr       = enabled ? self->cga.vram[(addr + ((x << 1) + 1)) & 0x7fff] : 0x00;\n        const uint8_t hi_bit     = attr & 0x08;\n        const int     drawcursor = ((ma == cursoraddr) && cursorline && enabled && (self->cga.cgablink & 0x10));\n        int           underline  = ((attr & 0x07) == 0x01) || ((hi_mode == 1) && hi_bit);\n        int           blink      = 0;\n        uint32_t      c1;\n        uint32_t      c0;\n\n        if (underline)\n            attr = attr | 0x7;\n        c1 = blinkcols[attr][1];\n        if (self->cga.cgamode & CGA_MODE_FLAG_BLINK) {\n            c0 = blinkcols[attr][0];\n            if ((self->cga.cgablink & 0x08) && (attr & 0x80) && !drawcursor) {\n                c1    = c0;\n                blink = 1;\n            }\n        } else {\n            c1 = normcols[attr][1];\n            c0 = normcols[attr][0];\n        }\n        uint16_t chr_addr = ((chr * 16) + scanline) & 0x0fff;\n        if ((hi_mode == 3) && hi_bit)\n            chr_addr |= 0x1000;\n        const uint8_t font = self->font_ram[chr_addr];\n        const bool    solid = underline && (scanline == 7);\n        uint32_t      dots;\n        uint32_t      on;\n        uint32_t      off;\n\n        /* The first drawing of the cell, then (high-intensity attributes in modes 4 and 2) the one over it */\n        if (solid)\n            dots = 0xff, on = off = mdaattr[attr][blink][1];\n        else if (drawcursor)\n            dots = font, on = c1 ^ X, off = c0 ^ X;\n        else\n            dots = font, on = c1, off = c0;\n        if (hi_bit && (hi_mode == 4) && !solid) {\n            const uint32_t h1 = plasma_half(c1);\n            const uint32_t h0 = plasma_half(c0);\n            dots = font, on = drawcursor ? (h1 ^ XH) : h1, off = drawcursor ? (h0 ^ XH) : h0;\n        } else if (hi_bit && (hi_mode == 2) && !solid)\n            dots = font, on = drawcursor ? (c0 ^ X) : c0, off = drawcursor ? (c1 ^ X) : c1; /* dots set take colour 0 */\n        const int f = plasma_k_colour(palette, &n, on);\n        const int b = plasma_k_colour(palette, &n, off);\n        if ((f < 0) || (b < 0)) {\n            kairo_gpu_scan_touch(bitmap, out, (uint32_t) bitmap->w);\n            return false;\n        }\n        cells[x] = dots | ((uint32_t) f << 8) | ((uint32_t) b << 16);\n        ma++;\n    }\n    uint32_t *line = kairo_gpu_scan(bitmap, bitmap->kairo_gpu, out, KAIRO_SCAN_TEXT, (uint32_t) cols * ((cols == 80) ? 8 : 16), (uint32_t) cols,\n                                    palette, n, 8, 0, (cols == 80) ? 0 : KAIRO_SCAN_WIDE);\n    memcpy(line, cells, (size_t) cols * sizeof(uint32_t));\n    kairo_gpu_scan_commit();\n    return true;\n}\n\nstatic void\ncompaq_plasma_poll(void *priv)\n"),
    ('86box/src/video/vid_cga_compaq_plasma.c',
     '\n                /* 80-col */\n                if (self->cga.cgamode & 0x01) {\n                    scanline = self->cga.displine & 0x0f;\n',
     '\n                /* KairoX86#312: the GPU draws the line, else the CPU (the row touched for it) */\n                if (compaq_plasma_render_gpu(self, memaddr, cursoraddr)) {\n                }\n                /* 80-col */\n                else if (self->cga.cgamode & 0x01) {\n                    scanline = self->cga.displine & 0x0f;\n'),
]

# KairoX86#317: the IBM PC Convertible's LCD on the GPU: each dot's next response level worked out as ever, the rows
# to the GPU as a level a byte through the levels' colours (where the monitor's picture is shared with the GPU).
KAIROX86_GPU_IBM5140 = [
    ('86box/src/video/vid_ibm5140.c',
     '#include <86box/video.h>\n#include <86box/vid_cga.h>\n',
     '#include <86box/video.h>\n#include <86box/kairo_gpu.h> /* KairoX86#317 */\n#include <86box/vid_cga.h>\n'),
    ('86box/src/video/vid_ibm5140.c',
     '    video_wait_for_buffer_monitor(video->monitor);\n    for (unsigned y = 0; y < LCD_HEIGHT; y++) {\n        uint32_t *line = monitor->target_buffer->line[y];\n',
     "    video_wait_for_buffer_monitor(video->monitor);\n    /* KairoX86#317: with Hardware acceleration on (and the monitor's picture shared with the GPU), each dot's next\n       level, the panel's response, worked out here as ever, and the row to the GPU's scanout queue as a level a byte\n       through the levels' colours */\n    bitmap_t *bitmap = monitor->target_buffer;\n    if (kairo_gpu_on && (bitmap->kairo_gpu != NULL)) {\n        for (unsigned y = 0; y < LCD_HEIGHT; y++) {\n            uint8_t *levels = (uint8_t *) kairo_gpu_scan(bitmap, bitmap->kairo_gpu, (uint32_t) (bitmap->line[y] - bitmap->dat), KAIRO_SCAN_8,\n                                                         LCD_WIDTH, LCD_WIDTH / 4, level_color, LCD_LEVELS, 0xff, 0, 0);\n            for (unsigned column = 0; column < LCD_WIDTH / 8; column++) {\n                const uint8_t data = enabled ? lcd_byte(video, column, y) : 0;\n                for (unsigned bit = 0; bit < 8; bit++) {\n                    const uint8_t next     = next_level[(data & (0x80 >> bit)) != 0][*level];\n                    *level++               = next;\n                    levels[column * 8 + bit] = next;\n                }\n            }\n            kairo_gpu_scan_commit();\n        }\n    } else for (unsigned y = 0; y < LCD_HEIGHT; y++) {\n        uint32_t *line = monitor->target_buffer->line[y];\n"),
]

# KairoX86#311: the IBM 3270 PC's display adapter on the GPU (pc3270_render_gpu): 9-dot text cells (underline and
# cursor solid), the native and CGA graphics; not while the diagnostic readback samples the CPU's pixels.
KAIROX86_GPU_PC3270 = [
    ('86box/src/video/vid_3270pc.c',
     '#include <86box/video.h>\n#include <86box/plat_unused.h>\n',
     '#include <86box/video.h>\n#include <86box/kairo_gpu.h> /* KairoX86#311 */\n#include <86box/plat_unused.h>\n'),
    ('86box/src/video/vid_3270pc.c',
     '}\n\nstatic void\npc3270_poll(void *priv)\n',
     "}\n\n/* KairoX86#311: the line dev->render draws (read as it reads it) to the GPU's scanout queue in its colours; returns\n   whether the GPU draws it. The blank lines (the CGA modes' below 200, a display turned off) are the CPU's. */\nstatic bool\npc3270_render_gpu(pc3270_t *dev)\n{\n    bitmap_t      *bitmap = buffer32;\n    const uint32_t out    = (uint32_t) (bitmap->line[dev->displine] - bitmap->dat);\n    const int      width  = dev->cols * 9;\n\n    if ((width <= 0) || (width > 2048))\n        return false;\n    if (dev->render == pc3270_render_text) {\n        int            scanline  = dev->displine % dev->charheight;\n        int            row       = dev->displine / dev->charheight;\n        int            underline = dev->ir[7] & 0x0f;\n        int            curstop   = (dev->ir[6] >> 4) & 0x0f;\n        int            cursbot   = dev->ir[6] & 0x0f;\n        uint16_t       pcoffset  = (uint16_t) (((dev->reg189 & 0x0f) << 8) | dev->reg18a);\n        int            blinkon   = dev->blink & 0x10;\n        int            cursblink = (dev->ir[7] & 0x20) ? (blinkon != 0) : 1;\n        uint32_t      *cells     = kairo_gpu_scan(bitmap, bitmap->kairo_gpu, out, KAIRO_SCAN_TEXT, (uint32_t) width, (uint32_t) dev->cols,\n                                                  dev->pal, 8, 9, 0, 0);\n        for (int x = 0; x < dev->cols; x++) {\n            uint16_t       ma   = (uint16_t) ((dev->scraddr + (row * dev->cols) + x) & 0x3fff);\n            const uint8_t *cell = &dev->tram[(ma & 0x7ff) * 4];\n            uint8_t        chr  = cell[0];\n            uint8_t        attr = cell[1];\n            uint16_t       glyph;\n            int            fg; /* indexes into dev->pal */\n            int            bg;\n            int            ul    = 0;\n            int            blink = 0;\n\n            if (chr != 0xff) {\n                int sel = (attr >> 6) & 3;\n                if (dev->colour) {\n                    fg = pc3270_attr_to_cga[(attr >> 3) & 7];\n                    bg = pc3270_attr_to_cga[attr & 7];\n                } else {\n                    fg = (attr & 0x20) ? 7 : 2;\n                    bg = 0;\n                }\n                blink = (sel == 1) && !blinkon;\n                if (sel == 2) {\n                    int t = fg;\n                    fg    = bg;\n                    bg    = t;\n                }\n                ul    = (sel == 3);\n                glyph = chr;\n            } else {\n                uint16_t ci = (uint16_t) (((ma + pcoffset) & 0x7ff) * 2);\n                uint8_t  ec = dev->cram[ci];\n                uint8_t  ea = dev->cram[ci + 1];\n                if (dev->colour) {\n                    fg = ea & 0x07;\n                    bg = (ea >> 4) & 0x07;\n                } else if ((ea & 0x77) == 0x70) {\n                    fg = 0;\n                    bg = 7;\n                } else {\n                    fg = (ea & 0x08) ? 7 : 2;\n                    bg = 0;\n                    ul = ((ea & 0x07) == 0x01);\n                }\n                blink = (ea & 0x80) && !blinkon;\n                glyph = 0x100 | ec;\n            }\n            if (blink)\n                fg = bg;\n            const uint16_t rowbits = dev->font[glyph][scanline] & 0x1ff;\n            uint32_t       c       = (uint32_t) (rowbits >> 1) | ((rowbits & 1) ? (1u << 24) : 0) | ((uint32_t) fg << 8) | ((uint32_t) bg << 16);\n            if (ul && (scanline == underline)) /* every dot the foreground */\n                c = 0xff | (1u << 24) | ((uint32_t) fg << 8) | ((uint32_t) fg << 16);\n            if ((ma == dev->cursaddr) && dev->cursen && cursblink && (scanline >= curstop) && (scanline <= cursbot)) {\n                /* the cursor OR'd into the output: the foreground, or white on a cell whose colours are one */\n                const int cur = (dev->pal[fg] == dev->pal[bg]) ? 7 : fg;\n                c             = 0xff | (1u << 24) | ((uint32_t) cur << 8) | ((uint32_t) cur << 16);\n            }\n            cells[x] = c;\n        }\n        kairo_gpu_scan_commit();\n        return true;\n    }\n    if ((dev->render == pc3270_render_apa_1bpp) || (dev->render == pc3270_render_apa_2bpp)) {\n        const bool     one    = dev->render == pc3270_render_apa_1bpp;\n        const int      stride = pc3270_apa_stride(dev);\n        const uint32_t addr   = (uint32_t) (dev->displine * stride);\n        const int      bytes_n = (width + 7) / 8;\n        uint8_t        pal[4];\n        uint32_t       colours[4];\n        if (one) {\n            colours[0] = dev->pal[0];\n            colours[1] = dev->pal[7];\n        } else {\n            pc3270_gfx_palette(dev, pal);\n            for (int v = 0; v < 4; v++)\n                colours[v] = dev->pal[pal[v]];\n        }\n        uint8_t *bytes = (uint8_t *) kairo_gpu_scan(bitmap, bitmap->kairo_gpu, out, KAIRO_SCAN_BITS, (uint32_t) bytes_n * 8, ((uint32_t) bytes_n + 3) / 4,\n                                                    colours, one ? 2 : 4, one ? 1 : 2, 0, one ? 0 : KAIRO_SCAN_WIDE);\n        for (int b = 0; b < bytes_n; b++)\n            bytes[b] = dev->apa[(addr + (uint32_t) b) & (PC3270_APA_SIZE - 1)];\n        kairo_gpu_scan_commit();\n        return true;\n    }\n    if (((dev->render == pc3270_render_cga_1bpp) || (dev->render == pc3270_render_cga_2bpp)) && (dev->displine < 200)) {\n        /* 640 dots from the interleaved buffer, then palette 0 to the raster's end: 4 bits a dot, value 4 that colour */\n        const bool     one  = dev->render == pc3270_render_cga_1bpp;\n        const uint32_t addr = (uint32_t) (((dev->displine & 1) ? 0x2000 : 0x0000) + ((dev->displine >> 1) * 80));\n        uint8_t        pal[4];\n        uint32_t       colours[5];\n        if (one) {\n            colours[0] = dev->pal[0];\n            colours[1] = dev->pal[7];\n        } else {\n            pc3270_gfx_palette(dev, pal);\n            for (int v = 0; v < 4; v++)\n                colours[v] = dev->pal[pal[v]];\n        }\n        colours[4]     = dev->pal[0];\n        uint8_t *nibs  = (uint8_t *) kairo_gpu_scan(bitmap, bitmap->kairo_gpu, out, KAIRO_SCAN_BITS, (uint32_t) width, ((uint32_t) width / 2 + 4) / 4,\n                                                    colours, 5, 4, 0, 0);\n        for (int x = 0; x < width; x += 2) {\n            uint8_t pair = 0;\n            for (int k = 0; k < 2; k++) {\n                const int xx = x + k;\n                uint8_t   v  = 4;\n                if (xx < 640) {\n                    const uint8_t data = dev->apa[(addr + (uint32_t) (xx >> 3)) & (PC3270_APA_SIZE - 1)];\n                    v = one ? ((data & (0x80 >> (xx & 7))) ? 1 : 0) : ((data >> (6 - (((xx >> 1) & 3) * 2))) & 3);\n                }\n                pair = (uint8_t) ((pair << 4) | v);\n            }\n            nibs[x / 2] = pair;\n        }\n        kairo_gpu_scan_commit();\n        return true;\n    }\n    return false;\n}\n\nstatic void\npc3270_poll(void *priv)\n"),
    ('86box/src/video/vid_3270pc.c',
     '\n            dev->render(dev);\n\n',
     "\n            /* KairoX86#311: the GPU draws the line, else the CPU (after what the GPU still has to draw there); not while\n               the diagnostic readback samples the CPU's pixels */\n            if (!(kairo_gpu_on && !(dev->reg189 & 0x20) && pc3270_render_gpu(dev))) {\n                if (kairo_gpu_on)\n                    kairo_gpu_scan_touch(buffer32, (uint32_t) (buffer32->line[dev->displine] - buffer32->dat), (uint32_t) buffer32->w);\n                dev->render(dev);\n            }\n\n"),
]

# KairoX86#322: the Tandy 2000's video on the GPU: its 640 x 400 graphics as the three planes' bytes through the pens,
# its text as cells through the 16 greens, worked out as the CPU works out its dots.
KAIROX86_GPU_TANDY2K = [
    ('86box/src/video/vid_tandy2k.c',
     '#include <86box/video.h>\n#include <86box/device.h>\n',
     '#include <86box/video.h>\n#include <86box/kairo_gpu.h> /* KairoX86#322 */\n#include <86box/device.h>\n'),
    ('86box/src/video/vid_tandy2k.c',
     '\n    for (int y = 0; y < 400; y++) {\n',
     "\n    /* KairoX86#322: with Hardware acceleration on each row goes to the GPU's scanout queue as planar pixels, a dword\n       of the three planes' bytes for each 8 dots (the one-plane board's planes 1 and 2 none), through the pens */\n    if (kairo_gpu_on) {\n        uint32_t pens[16] = { 0 };\n        for (int i = 0; i < 8; i++)\n            pens[i] = pal32[i];\n        for (int y = 0; y < 400; y++) {\n            uint32_t *planes = kairo_gpu_scan(buffer32, buffer32->kairo_gpu, (uint32_t) (buffer32->line[y] - buffer32->dat),\n                                              KAIRO_SCAN_PLANES, TANDY2K_COLS * 8, TANDY2K_COLS, pens, 16, 0, 0, 0);\n            for (int sx = 0; sx < TANDY2K_COLS; sx++) {\n                const uint32_t off = (uint32_t) ((y * TANDY2K_COLS) + sx);\n                planes[sx]         = (uint32_t) vid->vram[0][off];\n                if (color_board)\n                    planes[sx] |= ((uint32_t) vid->vram[1][off] << 8) | ((uint32_t) vid->vram[2][off] << 16);\n            }\n            kairo_gpu_scan_commit();\n        }\n        return;\n    }\n\n    for (int y = 0; y < 400; y++) {\n"),
    ('86box/src/video/vid_tandy2k.c',
     '        green[i] = pen_green((uint8_t) i);\n\n',
     "        green[i] = pen_green((uint8_t) i);\n\n    /* KairoX86#322: with Hardware acceleration on each scan line goes to the GPU's scanout queue as text cells, their\n       pens indexes into the 16 greens, worked out as the CPU works out its dots */\n    if (kairo_gpu_on) {\n        for (int row = 0; row < TANDY2K_ROWS; row++) {\n            for (int line = 0; line < 16; line++) {\n                uint32_t *cells = kairo_gpu_scan(buffer32, buffer32->kairo_gpu,\n                                                 (uint32_t) (buffer32->line[(row * 16) + line] - buffer32->dat), KAIRO_SCAN_TEXT,\n                                                 TANDY2K_COLS * 8, TANDY2K_COLS, green, 16, 8, 0, 0);\n                for (int col = 0; col < TANDY2K_COLS; col++) {\n                    uint32_t cell  = (uint32_t) ((row * TANDY2K_COLS) + col) * 2;\n                    uint8_t *cellp = vid_cell_ptr(vid, fb + cell);\n                    uint8_t  bits  = 0x00;\n                    uint32_t fg    = 0x0f;\n                    uint32_t bg    = 0x00;\n\n                    if (cellp != NULL) {\n                        const uint8_t code = cellp[0];\n                        const uint8_t attr = cellp[1];\n                        const uint8_t pen  = (uint8_t) (4 | ((attr & 0x40) ? 0 : 2));\n                        bits               = vid->chram[((code & 0x80) ? 0x1000 : 0x0000) + ((code & 0x7f) * 32) + (line * 2)];\n                        fg                 = vid->pal[pen | 1];\n                        bg                 = vid->pal[pen];\n                        if (attr & 0x04)\n                            bits = 0x00;\n                        if (attr & 0x80)\n                            bits = (uint8_t) ~bits;\n                        if ((attr & 0x20) && blink_off)\n                            bits = 0x00;\n                    }\n                    if (cursor_on && (row == vid->vpac[0x18]) && (col == vid->vpac[0x19]))\n                        bits = (uint8_t) ~bits;\n                    cells[col] = bits | ((fg & 0x0f) << 8) | ((bg & 0x0f) << 16);\n                }\n                kairo_gpu_scan_commit();\n            }\n        }\n        return;\n    }\n\n"),
]

# KairoX86#324: the IBM 5550's display on the GPU. epoch_render_text composes each line as palette indexes (its logic
