# KairoX86#257, #259: the Hercules blend on the GPU: video_blend_monitor's step taken out as video_blend_codes (each pixel
# of an 8-pixel group its code, 0 to 2: its own bit and its left neighbour's, the carry from the group before, shared),
# which video_blend_monitor draws as 0, 7 or 15 as before and the Hercules and Hercules Plus GPU lines pack as 2-bit
# pixels through those colours.
KAIROX86_GPU_HERC_BLEND = [
    ('86box/src/video/video.c',
     '\nvoid\nvideo_blend_monitor(int x, int y, int monitor_index)\n{\n    uint32_t            pixels32_1;\n    uint32_t            pixels32_2;\n    unsigned int        val1;\n    unsigned int        val2;\n    static unsigned int carry = 0;\n\n    if (!herc_blend)\n        return;\n\n    if (!x)\n        carry = 0;\n\n    val1       = pixels8(&(monitors[monitor_index].target_buffer->line[y][x]));\n    val2       = (val1 >> 1) + carry;\n    carry      = (val1 & 1) << 7;\n    pixels32_1 = cga_2_table[val1 >> 4] + cga_2_table[val2 >> 4];\n    pixels32_2 = cga_2_table[val1 & 0xf] + cga_2_table[val2 & 0xf];\n    for (uint8_t xx = 0; xx < 4; xx++) {\n        monitors[monitor_index].target_buffer->line[y][x + xx]       = pixel_to_color((uint8_t *) &pixels32_1, xx);\n        monitors[monitor_index].target_buffer->line[y][x + (xx | 4)] = pixel_to_color((uint8_t *) &pixels32_2, xx);\n    }\n}\n',
     "\n/* The blend's carry: the last pixel of the group before (KairoX86#257: shared by video_blend_codes' callers) */\nstatic unsigned int blend_carry = 0;\n\nvoid\nvideo_blend_codes(uint8_t bits, int reset, uint8_t *codes)\n{\n    uint32_t     pixels32_1;\n    uint32_t     pixels32_2;\n    unsigned int val1;\n    unsigned int val2;\n\n    if (reset)\n        blend_carry = 0;\n\n    val1        = bits;\n    val2        = (val1 >> 1) + blend_carry;\n    blend_carry = (val1 & 1) << 7;\n    pixels32_1  = cga_2_table[val1 >> 4] + cga_2_table[val2 >> 4];\n    pixels32_2  = cga_2_table[val1 & 0xf] + cga_2_table[val2 & 0xf];\n    for (uint8_t xx = 0; xx < 4; xx++) {\n        codes[xx]       = ((uint8_t *) &pixels32_1)[xx] & 0x03;\n        codes[xx | 4]   = ((uint8_t *) &pixels32_2)[xx] & 0x03;\n    }\n}\n\nvoid\nvideo_blend_monitor(int x, int y, int monitor_index)\n{\n    static const uint32_t colour[4] = { 0x00, 0x07, 0x0f, 0x00 }; /* pixel_to_color's */\n    uint8_t               codes[8];\n\n    if (!herc_blend)\n        return;\n\n    video_blend_codes(pixels8(&(monitors[monitor_index].target_buffer->line[y][x])), !x, codes);\n    for (uint8_t xx = 0; xx < 8; xx++)\n        monitors[monitor_index].target_buffer->line[y][x + xx] = colour[codes[xx]];\n}\n"),
    ('86box/src/video/vid_hercules.c',
     "    const uint32_t columns = dev->crtc[1];\n    if (!kairo_gpu_on || (columns == 0) || ((dev->ctrl & 0x02) && herc_blend))\n        return false; /* the CPU draws it: hercules_render_overscan_left drew the row's queued drawing first */\n    bitmap_t      *bitmap = buffer32;\n    uint32_t      *pixels = &bitmap->line[dev->displine + 14][8];\n    const uint32_t out    = (uint32_t) (pixels - bitmap->dat);\n    if (dev->ctrl & 0x02) {\n        /* Graphics: 16 pixels of 1 bit a column, colour 7 or 0 */\n        uint32_t base = (dev->scanline & 3) * 0x2000;\n        if (dev->ctrl & 0x80)\n            base += 0x8000;\n        const uint32_t colours[2] = { pal_lookup[0], pal_lookup[7] };\n",
     "    const uint32_t columns = dev->crtc[1];\n    if (!kairo_gpu_on || (columns == 0))\n        return false; /* the CPU draws it: hercules_render_overscan_left drew the row's queued drawing first */\n    bitmap_t      *bitmap = buffer32;\n    uint32_t      *pixels = &bitmap->line[dev->displine + 14][8];\n    const uint32_t out    = (uint32_t) (pixels - bitmap->dat);\n    if (dev->ctrl & 0x02) {\n        /* Graphics: 16 pixels of 1 bit a column, colour 7 or 0 */\n        uint32_t base = (dev->scanline & 3) * 0x2000;\n        if (dev->ctrl & 0x80)\n            base += 0x8000;\n        if (herc_blend) { /* KairoX86#257: the blend's codes, 2 bits a pixel, as video_blend draws them */\n            const uint32_t colours[4] = { pal_lookup[0], pal_lookup[7], pal_lookup[15], pal_lookup[0] };\n            uint8_t       *bytes      = (uint8_t *) kairo_gpu_scan(bitmap, bitmap->kairo_gpu, out, KAIRO_SCAN_BITS, columns * 16,\n                                                                   (columns * 4 + 3) / 4, colours, 4, 2, 0, 0);\n            for (uint32_t x = 0; x < columns; x++) {\n                const uint32_t at = ((dev->memaddr << 1) & 0x1fff) + base;\n                for (uint32_t h = 0; h < 2; h++) {\n                    uint8_t codes[8];\n                    video_blend_codes((dev->ctrl & 8) ? dev->vram[at + h] : 0, 0, codes); /* its x never 0 (8 on) */\n                    bytes[x * 4 + h * 2]     = (uint8_t) ((codes[0] << 6) | (codes[1] << 4) | (codes[2] << 2) | codes[3]);\n                    bytes[x * 4 + h * 2 + 1] = (uint8_t) ((codes[4] << 6) | (codes[5] << 4) | (codes[6] << 2) | codes[7]);\n                }\n                dev->memaddr++;\n            }\n            kairo_gpu_scan_commit();\n            return true;\n        }\n        const uint32_t colours[2] = { pal_lookup[0], pal_lookup[7] };\n"),
    ('86box/src/video/vid_hercules_plus.c',
     '    const uint32_t out    = (uint32_t) (bitmap->line[dev->displine] - bitmap->dat);\n    if ((columns == 0) || (graphics && herc_blend)) {\n        /* The CPU draws the line: a queued drawing of the row (the frame restarted) first */\n        kairo_gpu_scan_touch(bitmap, out, (uint32_t) bitmap->w);\n        return false;\n    }\n    if (graphics) {\n        uint32_t base = (dev->scanline & 3) * 0x2000;\n        if ((dev->ctrl & HERCULESPLUS_CTRL_PAGE1) && (dev->ctrl2 & HERCULESPLUS_CTRL2_PAGE1))\n            base += 0x8000;\n        const uint32_t colours[2] = { pal_lookup[0], pal_lookup[7] };\n',
     "    const uint32_t out    = (uint32_t) (bitmap->line[dev->displine] - bitmap->dat);\n    if (columns == 0) {\n        /* The CPU draws the line: a queued drawing of the row (the frame restarted) first */\n        kairo_gpu_scan_touch(bitmap, out, (uint32_t) bitmap->w);\n        return false;\n    }\n    if (graphics) {\n        uint32_t base = (dev->scanline & 3) * 0x2000;\n        if ((dev->ctrl & HERCULESPLUS_CTRL_PAGE1) && (dev->ctrl2 & HERCULESPLUS_CTRL2_PAGE1))\n            base += 0x8000;\n        if (herc_blend) { /* KairoX86#259: the blend's codes, 2 bits a pixel, as video_blend draws them */\n            const uint32_t colours[4] = { pal_lookup[0], pal_lookup[7], pal_lookup[15], pal_lookup[0] };\n            uint8_t       *bytes      = (uint8_t *) kairo_gpu_scan(bitmap, bitmap->kairo_gpu, out, KAIRO_SCAN_BITS, columns * 16,\n                                                                   (columns * 4 + 3) / 4, colours, 4, 2, 0, 0);\n            for (uint32_t x = 0; x < columns; x++) {\n                const uint32_t at = ((dev->memaddr << 1) & 0x1fff) + base;\n                for (uint32_t h = 0; h < 2; h++) {\n                    uint8_t codes[8];\n                    video_blend_codes((dev->ctrl & 8) ? dev->vram[at + h] : 0, (x == 0) && (h == 0), codes); /* its x 0 first */\n                    bytes[x * 4 + h * 2]     = (uint8_t) ((codes[0] << 6) | (codes[1] << 4) | (codes[2] << 2) | codes[3]);\n                    bytes[x * 4 + h * 2 + 1] = (uint8_t) ((codes[4] << 6) | (codes[5] << 4) | (codes[6] << 2) | codes[7]);\n                }\n                dev->memaddr++;\n            }\n            kairo_gpu_scan_commit();\n            return true;\n        }\n        const uint32_t colours[2] = { pal_lookup[0], pal_lookup[7] };\n"),
    ('86box/src/include/86box/video.h',
     'extern void video_blend_monitor(int x, int y, int monitor_index);\nextern void video_process_8_monitor(int x, int y, int monitor_index);\n',
     "extern void video_blend_monitor(int x, int y, int monitor_index);\n/* KairoX86#257: one 8-pixel group of the blend (bits: its pixels, the leftmost the MSB; reset as video_blend_monitor's\n   x of 0 resets it): each pixel's code, 0, 1 or 2, which video_blend_monitor draws as colour 0, 7 or 15 */\nextern void video_blend_codes(uint8_t bits, int reset, uint8_t *codes);\nextern void video_process_8_monitor(int x, int y, int monitor_index);\n"),
]

