# KairoX86#283: the Rage 128 GPU backend reports the triangles its kernels drew at close (kairo-gpu-r128: N triangles
# drawn), as the other engines do, so the graphics batch shows its 3D work on the PC and on a device.
KAIROX86_GPU_R128_DRAWN_REPORT = [
    ('86box/src/video/vid_ati_rage128_gpu.c',
     '    gpu_stats_core(dev, g);\n    gpu_stats_prof_waits(g);\n',
     '    gpu_stats_core(dev, g);\n    /* How many triangles the GPU kernels drew, for the graphics batch\n       (core/test/gpu/compare.py sums every engine\'s report, KairoX86#283) */\n    fprintf(stderr, "kairo-gpu-r128: %llu triangles drawn\\n", (unsigned long long) g->st_tris);\n    gpu_stats_prof_waits(g);\n'),
]

# KairoX86#289: the ARM64 Voodoo recompiler drawing what the C rasteriser draws, checked on the RP6 (compare.py --a off
# --b off+rec): every instruction macro's operand in its own parentheses (ARM64_LSL_IMM(d, n, sub2 ? 2 : 4) encoded a
# right shift, which broke subtractive dithering); the perspective S and T shifts rounded as the C code and the x86-64
# recompiler round them; whether a block needs its alpha decided by voodoo_codegen_alpha_used, as the x86-64 one
# decides it, and the colour combine's alocal add (CC_ADD_ALOCAL) added.
KAIROX86_VOODOO_ARM64_EXACT = [
    ('86box/src/include/86box/vid_voodoo_codegen_arm64.h',
     ' * The instruction stores offset/8 in bits [21:15] (7-bit scaled immediate). */\n#define IMM7_X(imm_data) (((imm_data >> 3) & 0x7f) << 15)\n#define IMM12(imm_data)  ((imm_data) << 10)\n#define IMM16(imm_data)  ((imm_data) << 5)\n\n#define IMMN(immn) ((immn) << 22)\n#define IMMR(immr) ((immr) << 16)\n#define IMMS(imms) ((imms) << 10)\n#define IMM_LOGICAL(imm) ((imm) << 10)\n\n/* ========================================================================\n * Section 4: Offset Encoding Helpers\n * ======================================================================== */\n#define OFFSET14(offset)  (((offset >> 2) << 5) & 0x0007ffe0)\n#define OFFSET19(offset)  (((offset >> 2) << 5) & 0x00ffffe0)\n#define OFFSET20(offset)  (((offset & 3) << 29) | ((((offset) & 0x1fffff) >> 2) << 5))\n#define OFFSET26(offset)  ((offset >> 2) & 0x03ffffff)\n\n',
     ' * The instruction stores offset/8 in bits [21:15] (7-bit scaled immediate). */\n#define IMM7_X(imm_data) ((((imm_data) >> 3) & 0x7f) << 15)\n#define IMM12(imm_data)  ((imm_data) << 10)\n#define IMM16(imm_data)  ((imm_data) << 5)\n\n#define IMMN(immn) ((immn) << 22)\n#define IMMR(immr) ((immr) << 16)\n#define IMMS(imms) ((imms) << 10)\n#define IMM_LOGICAL(imm) ((imm) << 10)\n\n/* ========================================================================\n * Section 4: Offset Encoding Helpers\n * ======================================================================== */\n#define OFFSET14(offset)  ((((offset) >> 2) << 5) & 0x0007ffe0)\n#define OFFSET19(offset)  ((((offset) >> 2) << 5) & 0x00ffffe0)\n#define OFFSET20(offset)  ((((offset) & 3) << 29) | ((((offset) & 0x1fffff) >> 2) << 5))\n#define OFFSET26(offset)  (((offset) >> 2) & 0x03ffffff)\n\n'),
    ('86box/src/include/86box/vid_voodoo_codegen_arm64.h',
     '/* LSL Wd, Wn, #imm */\n#define ARM64_LSL_IMM(d, n, imm) (0x53000000 | IMMR((-imm) & 0x1F) | IMMS(31 - (imm)) | Rn(n) | Rd(d))\n\n/* LSL Xd, Xn, #imm -- 64-bit */\n#define ARM64_LSL_IMM_X(d, n, imm) (0xD3400000 | IMMR((-imm) & 0x3F) | IMMS(63 - (imm)) | Rn(n) | Rd(d))\n\n',
     '/* LSL Wd, Wn, #imm */\n#define ARM64_LSL_IMM(d, n, imm) (0x53000000 | IMMR((-(imm)) & 0x1F) | IMMS(31 - (imm)) | Rn(n) | Rd(d))\n\n/* LSL Xd, Xn, #imm -- 64-bit */\n#define ARM64_LSL_IMM_X(d, n, imm) (0xD3400000 | IMMR((-(imm)) & 0x3F) | IMMS(63 - (imm)) | Rn(n) | Rd(d))\n\n'),
    ('86box/src/include/86box/vid_voodoo_codegen_arm64.h',
     '/* STP Dt1, Dt2, [Xn, #imm] -- SIMD store pair (64-bit NEON) */\n#define ARM64_STP_D(t1, t2, n, imm) (0x6D000000 | (((imm >> 3) & 0x7F) << 15) | Rt2(t2) | Rn(n) | Rt(t1))\n\n/* LDP Dt1, Dt2, [Xn, #imm] -- SIMD load pair (64-bit NEON) */\n#define ARM64_LDP_D(t1, t2, n, imm) (0x6D400000 | (((imm >> 3) & 0x7F) << 15) | Rt2(t2) | Rn(n) | Rt(t1))\n\n',
     '/* STP Dt1, Dt2, [Xn, #imm] -- SIMD store pair (64-bit NEON) */\n#define ARM64_STP_D(t1, t2, n, imm) (0x6D000000 | ((((imm) >> 3) & 0x7F) << 15) | Rt2(t2) | Rn(n) | Rt(t1))\n\n/* LDP Dt1, Dt2, [Xn, #imm] -- SIMD load pair (64-bit NEON) */\n#define ARM64_LDP_D(t1, t2, n, imm) (0x6D400000 | ((((imm) >> 3) & 0x7F) << 15) | Rt2(t2) | Rn(n) | Rt(t1))\n\n'),
    ('86box/src/include/86box/vid_voodoo_codegen_arm64.h',
     '\n        /* ASR x5, x5, #14 -- S >>= 14 */\n        addlong(ARM64_ASR_IMM_X(5, 5, 14));\n        /* ASR x6, x6, #14 -- T >>= 14 */\n        addlong(ARM64_ASR_IMM_X(6, 6, 14));\n\n        /* MUL x5, x5, x4 -- S *= quotient */\n        addlong(ARM64_MUL_X(5, 5, 4));\n        /* MUL x6, x6, x4 -- T *= quotient */\n        addlong(ARM64_MUL_X(6, 6, 4));\n\n',
     "\n        /* KairoX86#289: both shifts rounded, as the C code's voodoo_tmu_fetch and the x86-64 recompiler round them\n           (else texels land one off at texel edges): x10 = 1 << 13, added to S and T */\n        addlong(ARM64_MOVZ_X_HW(10, 0x2000, 0));\n        addlong(ARM64_ADD_REG_X(5, 5, 10));\n        addlong(ARM64_ADD_REG_X(6, 6, 10));\n\n        /* ASR x5, x5, #14 -- S >>= 14 */\n        addlong(ARM64_ASR_IMM_X(5, 5, 14));\n        /* ASR x6, x6, #14 -- T >>= 14 */\n        addlong(ARM64_ASR_IMM_X(6, 6, 14));\n\n        /* MUL x5, x5, x4 -- S *= quotient */\n        addlong(ARM64_MUL_X(5, 5, 4));\n        /* MUL x6, x6, x4 -- T *= quotient */\n        addlong(ARM64_MUL_X(6, 6, 4));\n\n        /* KairoX86#289: x10 = 1 << 29, the second shift's rounding */\n        addlong(ARM64_MOVZ_X_HW(10, 0x2000, 1));\n        addlong(ARM64_ADD_REG_X(5, 5, 10));\n        addlong(ARM64_ADD_REG_X(6, 6, 10));\n\n"),
    ('86box/src/include/86box/vid_voodoo_codegen_arm64.h',
     '    int amask_skip_pos   = 0;\n    int stipple_skip_pos = 0;\n',
     '    int amask_skip_pos   = 0;\n    /* KairoX86#289: whether the block needs a_other, a_local and the combined alpha, as the x86-64 recompiler\n       decides it (the alpha mask, the colour combine and the alpha planes need them too, not only the alpha test\n       and blend) */\n    int alpha_used       = voodoo_codegen_alpha_used(params);\n    int stipple_skip_pos = 0;\n'),
    ('86box/src/include/86box/vid_voodoo_codegen_arm64.h',
     '     * ---------------------------------------------------------------- */\n    if (params->alphaMode & ((1 << 0) | (1 << 4))) {\n        /* a_other (EBX) -> w14 */\n',
     '     * ---------------------------------------------------------------- */\n    if (alpha_used) {\n        /* a_other (EBX) -> w14 */\n'),
    ('86box/src/include/86box/vid_voodoo_codegen_arm64.h',
     '     * ---------------------------------------------------------------- */\n    if (params->alphaMode & ((1 << 0) | (1 << 4))) {\n        if (!(cca_mselect == 0 && cca_reverse_blend == 0)) {\n',
     '     * ---------------------------------------------------------------- */\n    if (alpha_used) {\n        if (!(cca_mselect == 0 && cca_reverse_blend == 0)) {\n'),
    ('86box/src/include/86box/vid_voodoo_codegen_arm64.h',
     '    if (!(cc_mselect == 0 && cc_reverse_blend == 0) && cc_mselect == CC_MSELECT_AOTHER) {\n        if (params->alphaMode & ((1 << 0) | (1 << 4))) {\n            addlong(ARM64_DUP_V4H_GPR(3, 12));\n        } else {\n            addlong(ARM64_MOVI_V2D_ZERO(3));\n        }\n    }\n\n    /* cca_add: add a_local to result */\n    if (cca_add && (params->alphaMode & ((1 << 0) | (1 << 4)))) {\n        addlong(ARM64_ADD_REG(12, 12, 15));\n    }\n\n    /* Clamp alpha result to [0, 0xFF] */\n    if (params->alphaMode & ((1 << 0) | (1 << 4))) {\n        addlong(ARM64_MOVZ_W(10, 0xFF));\n',
     '    if (!(cc_mselect == 0 && cc_reverse_blend == 0) && cc_mselect == CC_MSELECT_AOTHER) {\n        addlong(ARM64_DUP_V4H_GPR(3, 12));\n    }\n\n    /* cca_add: add a_local to result */\n    if (cca_add && alpha_used) {\n        addlong(ARM64_ADD_REG(12, 12, 15));\n    }\n\n    /* Clamp alpha result to [0, 0xFF] */\n    if (alpha_used) {\n        addlong(ARM64_MOVZ_W(10, 0xFF));\n'),
    ('86box/src/include/86box/vid_voodoo_codegen_arm64.h',
     '                /* Broadcast a_local (w15) to all 4 lanes of v3 */\n                if (params->alphaMode & ((1 << 0) | (1 << 4))) {\n                    addlong(ARM64_DUP_V4H_GPR(3, 15));\n                } else {\n                    /* Need to compute a_local if not done above */\n                    switch (cca_localselect) {\n                        case CCA_LOCALSELECT_ITER_A:\n                            addlong(ARM64_LDR_W(4, 0, STATE_ia));\n                            addlong(ARM64_ASR_IMM(4, 4, 12));\n                            addlong(ARM64_MOVZ_W(10, 0xFF));\n                            addlong(ARM64_BIC_REG_ASR(4, 4, 4, 31));   /* zero if negative */\n                            addlong(ARM64_CMP_IMM(4, 0xFF));\n                            addlong(ARM64_CSEL(4, 10, 4, COND_HI));    /* cap at 0xFF */\n                            break;\n                        case CCA_LOCALSELECT_COLOR0:\n                            addlong(ARM64_LDRB_IMM(4, 1, PARAMS_color0 + 3));\n                            break;\n                        case CCA_LOCALSELECT_ITER_Z:\n                            addlong(ARM64_LDR_W(4, 0, STATE_z));\n                            addlong(ARM64_ASR_IMM(4, 4, 20));\n                            addlong(ARM64_MOVZ_W(10, 0xFF));\n                            addlong(ARM64_BIC_REG_ASR(4, 4, 4, 31));   /* zero if negative */\n                            addlong(ARM64_CMP_IMM(4, 0xFF));\n                            addlong(ARM64_CSEL(4, 10, 4, COND_HI));    /* cap at 0xFF */\n                            break;\n                        default:\n                            addlong(ARM64_MOVZ_W(4, 0xFF));\n                            break;\n                    }\n                    addlong(ARM64_DUP_V4H_GPR(3, 4));\n                }\n                break;\n',
     '                /* Broadcast a_local (w15) to all 4 lanes of v3 */\n                addlong(ARM64_DUP_V4H_GPR(3, 15));\n                break;\n'),
    ('86box/src/include/86box/vid_voodoo_codegen_arm64.h',
     '\n    /* cc_add: add clocal back */\n    if (cc_add == 1) {\n        addlong(ARM64_ADD_V4H(0, 0, 1));\n    }\n',
     '\n    /* cc_add: add clocal back, or a_local in every channel (KairoX86#289: as the C code and the x86-64 recompiler) */\n    if (cc_add == CC_ADD_CLOCAL) {\n        addlong(ARM64_ADD_V4H(0, 0, 1));\n    } else if (cc_add == CC_ADD_ALOCAL) {\n        addlong(ARM64_DUP_V4H_GPR(3, 15));\n        addlong(ARM64_ADD_V4H(0, 0, 3));\n    }\n'),
]

# KairoX86#308: the IBM PGC's POLY draws its polygon, filled with the area pattern under PRMFIL, else its outline in
# the line pattern closed back to the first corner, as its other primitives draw; it read the corners and drew nothing.
KAIROX86_PGC_POLY = [
    ('86box/src/video/vid_pgc.c',
     '        if (!pgc_param_coord(dev, &y[n]))\n            return;\n    }\n}\n',
     "        if (!pgc_param_coord(dev, &y[n]))\n            return;\n    }\n    if (count == 0)\n        return;\n\n    /* KairoX86#308: drawn as the PGC's other primitives are, filled under PRMFIL (the area pattern), else its\n       outline in the line pattern, closed back to the first corner */\n    if (dev->fill_mode)\n        pgc_fill_polygon(dev, count, x, y);\n    else {\n        uint16_t mask = dev->line_pattern;\n        for (uint8_t n = 1; n < count; n++)\n            mask = pgc_draw_line(dev, x[n - 1], y[n - 1], x[n], y[n], mask);\n        pgc_draw_line(dev, x[count - 1], y[count - 1], x[0], y[0], mask);\n    }\n}\n"),
]

# KairoX86#309: the IBM PGC's TEXT in ASCII mode takes its string as characters (text_char): the delimiter is the first
# one after the blanks, then the characters as sent, case kept, up to the same delimiter. It read a decimal number for
# the delimiter, rejected the quote and drew nothing.
KAIROX86_PGC_TEXT_ASCII = [
    ('86box/src/video/vid_pgc.c',
     "}\n\n/*\n * TEXT draws a string in the card's own font, justified about the current\n",
     "}\n\n/* KairoX86#309: one character of an ASCII-mode TEXT string, as the host sent it (input_char would upper-case it) */\nstatic int\ntext_char(pgc_t *dev, uint8_t *val)\n{\n    if (!dev->inputbyte(dev, val))\n        return 0;\n    *val &= 0x7f;\n    return 1;\n}\n\n/*\n * TEXT draws a string in the card's own font, justified about the current\n"),
    ('86box/src/video/vid_pgc.c',
     '\n    if (!pgc_param_byte(dev, &delim))\n        return;\n\n    while (count < sizeof(buf)) {\n        if (!pgc_param_byte(dev, &ch))\n            return;\n',
     "\n    /* KairoX86#309: in ASCII mode the string comes as characters, not numbers: its delimiter is the first one after\n       the blanks, then the characters as sent, case kept, up to the same delimiter */\n    const int ascii = dev->ascii_mode && !dev->clcur;\n\n    if (ascii) {\n        do {\n            if (!text_char(dev, &delim))\n                return;\n        } while ((delim == ' ') || (delim == '\\r') || (delim == '\\n') || (delim == '\\t'));\n    } else if (!pgc_param_byte(dev, &delim))\n        return;\n\n    while (count < sizeof(buf)) {\n        if (ascii ? !text_char(dev, &ch) : !pgc_param_byte(dev, &ch))\n            return;\n"),
]

# KairoX86#331: the IBM PGC's TJUST reads its two parameters as every byte parameter is read (pgc_param_byte):
# decimal in ASCII mode, from the list in a command list. It read them raw, so ASCII mode's TJUST 2,2 was a range error.
KAIROX86_PGC_TJUST = [
    ('86box/src/video/vid_pgc.c',
     '\n    if (!dev->inputbyte(dev, &param[0]))\n        return;\n    if (!dev->inputbyte(dev, &param[1]))\n        return;\n',
     '\n    /* KairoX86#331: as every byte parameter is read (decimal in ASCII mode, from the list in a command list) */\n    if (!pgc_param_byte(dev, &param[0]))\n        return;\n    if (!pgc_param_byte(dev, &param[1]))\n        return;\n'),
]

# KairoX86#306: 86Box's MIDI synths on the Munt and FluidSynth every Kairo core shares
# (shared/cmake/KairoMidi.cmake): the sound library links their targets in place of pkg-config or 86Box's
# own Munt copy (removed), FluidSynth takes the SoundFont the app ships in the ROM set
# (sound/kairo/GeneralUser-GS.sf2) when the player names none, and a SoundFont that does not load ends the
# machine with its name.
