    ('86box/src/pit_fast.c', 'pitf_reset(pitf_t *dev)\n{\n',
     'pitf_reset(pitf_t *dev)\n{\n    pitf_unlazy(); /* KairoX86#410 */\n'),
    ('86box/src/pit_fast.c', 'pitf_set_pit_const(void *data, uint64_t pit_const)\n{\n',
     'pitf_set_pit_const(void *data, uint64_t pit_const)\n{\n    pitf_unlazy(); /* KairoX86#410 */\n'),
    ('86box/src/pit_fast.c', 'pitf_ctr_set_clock_div(void *data, int counter_id, int div)\n{\n',
     'pitf_ctr_set_clock_div(void *data, int counter_id, int div)\n{\n    pitf_unlazy(); /* KairoX86#410 */\n'),
    ('86box/src/pit_fast.c', 'pitf_close(void *priv)\n{\n',
     'pitf_close(void *priv)\n{\n    pitf_unlazy(); /* KairoX86#410 */\n'),
    ('86box/src/pit_fast.c', '    pitf_t *pit = (pitf_t *)priv;\n    int l = ctr->l ? ctr->l : 0x10000;\n    if (ctr->disabled) {',
     '    pitf_t *pit = (pitf_t *)priv;\n    int l = ctr->l ? ctr->l : 0x10000;\n    if (ctr == pitf_lazy) { /* KairoX86#410: the skipped expiries, then this one as it was */\n        pitf_lazy_apply(PITF_LAZY_SPAN - 1);\n        pitf_lazy = NULL;\n    }\n    if (ctr->disabled) {'),
    ('86box/src/pit_fast.c', '        case 2: /*Rate generator*/\n            ctr->count += l;\n            if (ctr->using_timer)\n                timer_advance_u64(&ctr->timer, (uint64_t) (l * ctr->pit_const));\n            pitf_ctr_set_out(ctr, 0, pit);\n            pitf_ctr_set_out(ctr, 1, pit);\n            break;',
     '        case 2: /*Rate generator*/\n            ctr->count += l;\n            if (ctr->using_timer)\n                timer_advance_u64(&ctr->timer, (uint64_t) (l * ctr->pit_const));\n            pitf_ctr_set_out(ctr, 0, pit);\n            pitf_ctr_set_out(ctr, 1, pit);\n            /* KairoX86#410: a refresh counter running freely skips its next PITF_LAZY_SPAN - 1 expiries */\n            if ((pitf_lazy == NULL) && ctr->using_timer && ctr->enabled && !ctr->disabled && ctr->gate &&\n                (ctr->out_func == pit_refresh_timer_at) && ctr->out) {\n                pitf_lazy_period = (uint64_t) l * ctr->pit_const;\n                /* The timer was just put one period past this expiry */\n                pitf_lazy_base = ((((__uint128_t) ctr->timer.ts_integer) << 32) | ctr->timer.ts_frac) - pitf_lazy_period;\n                pitf_lazy_done = 0;\n                pitf_lazy_next = pitf_lazy_base + pitf_lazy_period;\n                pitf_lazy      = ctr;\n                const __uint128_t next = pitf_lazy_base + ((__uint128_t) PITF_LAZY_SPAN * pitf_lazy_period);\n                timer_disable(&ctr->timer);\n                ctr->timer.ts_integer = (uint64_t) (next >> 32);\n                ctr->timer.ts_frac    = (uint32_t) next;\n                timer_enable(&ctr->timer);\n            }\n            break;'),
    ('86box/src/pit_fast.c', 'pitf_init(const device_t *info)\n{\n',
     'pitf_init(const device_t *info)\n{\n    timer_before_tsc_set = pitf_lazy_before_tsc_set; /* KairoX86#410 */\n'),
    ('86box/src/port_6x.c', 'port_6x_write(uint16_t port, uint8_t val, void *priv)\n{\n',
     'port_6x_write(uint16_t port, uint8_t val, void *priv)\n{\n    pit_refresh_sync(); /* KairoX86#410 */\n'),
    ('86box/src/port_6x.c', 'port_61_read_simple(UNUSED(uint16_t port), UNUSED(void *priv))\n{\n',
     'port_61_read_simple(UNUSED(uint16_t port), UNUSED(void *priv))\n{\n    pit_refresh_sync(); /* KairoX86#410 */\n'),
    ('86box/src/port_6x.c', 'port_61_read(UNUSED(uint16_t port), void *priv)\n{\n',
     'port_61_read(UNUSED(uint16_t port), void *priv)\n{\n    pit_refresh_sync(); /* KairoX86#410 */\n'),
    ('86box/src/chipset/ali6117.c', '                    refresh_at_enable          = !(val & 0x02) || !!(dev->regs[0x20] & 0x80);',
     '                    pit_refresh_sync(); /* KairoX86#410 */\n                    refresh_at_enable          = !(val & 0x02) || !!(dev->regs[0x20] & 0x80);'),
    ('86box/src/chipset/ali6117.c', '                    refresh_at_enable = !(dev->regs[0x10] & 0x02) || !!(val & 0x80);',
     '                    pit_refresh_sync(); /* KairoX86#410 */\n                    refresh_at_enable = !(dev->regs[0x10] & 0x02) || !!(val & 0x80);'),
