    ('86box/src/timer.c', '#ifdef USE_DYNAREC\n    if (cpu_use_dynarec)\n        update_tsc();\n#endif\n\n    if (!timer_head) {\n        tsc = new_tsc;\n        return;\n    }\n',
     '#ifdef USE_DYNAREC\n    if (cpu_use_dynarec)\n        update_tsc();\n#endif\n    if (timer_before_tsc_set != NULL) /* KairoX86#410 */\n        timer_before_tsc_set();\n\n    if (!timer_head) {\n        tsc = new_tsc;\n        return;\n    }\n'),
